// Staff workspace: verification, onboarding (hospital / doctor registration, invitations), staff & access, inventory, approvals, reports,
// read-only Audit History and the extra Settings sections. Uses the existing page registry, components and styles; talks to the real API only.
(function () {
    'use strict';
    const S = window.Staff, esc = S.esc, $ = S.$, API = window.GoaAPI, U = S.ui, field = U.field;
    const call = (m, p, b) => S.req(() => API.call(m, p, b));
    const fq = () => (S.fid() ? 'facilityId=' + encodeURIComponent(S.fid()) : '');
    const q = (path, extra) => path + (path.includes('?') ? '&' : '?') + [fq(), extra].filter(Boolean).join('&');
    const ROLE = { manager: 'Administrator', nurse: 'Nurse / ward staff', reception: 'Front desk', pharmacy: 'Pharmacy / inventory', finance: 'Finance', doctor: 'Doctor' };
    const STATUS_TONE = { approved: 'ok', pending: 'warn', rejected: 'bad', suspended: 'bad', requested: 'warn', hospital_verified: 'info', ended: 'mute', redeemed: 'ok', revoked: 'mute', expired: 'mute', success: 'ok', failure: 'bad', blocked: 'bad', in_stock: 'ok', low: 'warn', out: 'bad', unchecked: 'warn', verified: 'ok', failed: 'bad' };
    const tone = s => S.badge(String(s).replace(/_/g, ' '), STATUS_TONE[s] || 'mute');
    const val = n => (document.getElementById(n) || {}).value || '';
    const note = (text, kind) => `<div class="notice n-${kind || 'info'}" style="margin-bottom:1rem"><i class="fa-solid fa-circle-info" aria-hidden="true"></i><span>${text}</span></div>`;
    const inp = (id, label, extra, hint) => field(id, label, `<input id="${id}" name="${id}" class="in" ${extra || ''}>`, hint);
    const sel = (id, label, list, hint) => field(id, label, `<select id="${id}" name="${id}" class="in">${list.map(o => `<option value="${esc(o[0])}">${esc(o[1])}</option>`).join('')}</select>`, hint);
    const dl = rows => `<dl class="kv">${rows.filter(Boolean).map(r => `<dt>${esc(r[0])}</dt><dd>${r[2] ? r[1] : esc(r[1] == null || r[1] === '' ? '-' : r[1])}</dd>`).join('')}</dl>`;
    const fail = (el, e) => { el.innerHTML = S.errorBox(e.message || 'Could not load.', true); const b = $('[data-retry]', el); if (b) b.onclick = () => S.rerender(); };
    const asked = async (title, label, opts) => {   // small "reason" / "password" prompt
        const o = opts || {};
        return S.modal({ title, submit: o.submit || 'Confirm', danger: o.danger, body: `${o.text ? `<p>${esc(o.text)}</p>` : ''}${o.reason ? field('mReason', label || 'Reason', '<textarea id="mReason" name="reason" class="in" rows="3" maxlength="400" ' + (o.reasonRequired ? 'required minlength="5"' : '') + '></textarea>') : ''}${o.password ? field('mPw', 'Confirm your password', '<input id="mPw" name="password" type="password" class="in" autocomplete="current-password" required>', 'Required for sensitive changes.') : ''}`,
            onSubmit: (d, f) => o.run({ reason: (f.get('reason') || '').trim(), password: f.get('password') || '' }) });
    };
    const fileToB64 = f => new Promise((res, rej) => { const r = new FileReader(); r.onload = () => res(String(r.result).split(',')[1]); r.onerror = () => rej(new Error('Could not read the file.')); r.readAsDataURL(f); });

    // Labels for the navigation (keys used by staff-boot.js)
    Object.assign(S.messages.en, { audit: 'Audit History', staffing: 'Staff & Access', inventory: 'Medicine Inventory', approvals: 'Approvals', verification: 'Verification', reports: 'Reports', onboarding: 'Register / Join' });

    // ====================================================== onboarding: register a hospital, register as a doctor, accept an invitation ======================================================
    async function onboarding(el, params) {
        let mine, doc;
        try { [mine, doc] = await Promise.all([call('GET', '/hospitals/mine'), call('GET', '/doctors/mine')]); } catch (e) { return fail(el, e); }
        const isPatient = S.user.role === 'patient';
        let justSubmitted = null; try { justSubmitted = sessionStorage.getItem('gcOnboardNote'); sessionStorage.removeItem('gcOnboardNote'); } catch (x) { /* ignore */ }
        el.innerHTML = S.head('Register or join GoaCare', 'Hospitals and doctors are listed as verified only after GoaCare checks them. Nothing here makes you staff by itself.')
            + (justSubmitted ? note('<strong>' + esc(justSubmitted) + '</strong> A GoaCare administrator will review it. Check this page for the status; you will get hospital or doctor access only after approval.', 'ok') : '')
            + `<div class="grid g2">
              <section class="card stack" aria-labelledby="oj"><h2 id="oj">Accept an invitation</h2><p class="muted small" style="margin:0">Your hospital administrator gave you a one-time link or code. It only works for the person it was issued to, and only once.</p>
                <form id="redeem" novalidate>${inp('invTok', 'Invitation code', 'autocomplete="off" required placeholder="gci_…" value="' + esc(params.token || '') + '"')}<div class="row-flex" style="margin-top:.6rem"><button class="btn btn-primary" type="submit">Join hospital</button><span id="invM" class="small" role="status"></span></div></form></section>
              <section class="card stack" aria-labelledby="od"><h2 id="od">Register as a doctor</h2>${doc.registration ? dl([['Status', tone(doc.registration.status), 1], ['Credential check', tone(doc.registration.credentialStatus), 1], ['Doctor ID', doc.registration.doctorCode || 'Issued after approval'], ['Registration no.', doc.registration.registrationNo]])
                + (doc.affiliations.length ? `<h3 style="margin:.4rem 0 0">Hospitals</h3><ul class="list">${doc.affiliations.map(a => `<li><span>${esc(a.facilityName)}</span>${tone(a.status)}</li>`).join('')}</ul>` : '')
                + (doc.registration.status === 'pending' ? `<div><label class="lbl" for="dFile">Add a supporting document (PDF, PNG or JPEG, up to 2 MB)</label><input id="dFile" type="file" accept="application/pdf,image/png,image/jpeg" class="in"><button class="btn" id="dUp" type="button" style="margin-top:.4rem">Upload</button></div>` : '')
                : `<form id="docReg" novalidate class="stack">${inp('dName', 'Full name', 'required minlength="3" maxlength="80"')}${inp('dQual', 'Qualifications', 'required maxlength="200" placeholder="e.g. MBBS, MD"')}<div class="grid g2">${inp('dReg', 'Medical registration number', 'required maxlength="40"')}${inp('dAuth', 'Issuing authority', 'required maxlength="100" placeholder="e.g. Goa Medical Council"')}</div><div class="grid g2">${inp('dSpec', 'Specialty', 'required maxlength="60"')}${inp('dDep', 'Department', 'maxlength="60"')}</div>${field('dFac', 'Hospital you work at', '<select id="dFac" class="in"><option value="">Choose later</option>' + S.facilities.filter(f => f.verificationStatus === 'approved').map(f => `<option value="${esc(f.id)}">${esc(f.name)}</option>`).join('') + '</select>', 'Only hospitals verified by GoaCare can be chosen.')}<div class="row-flex"><button class="btn btn-primary" type="submit">Submit for verification</button><span id="dM" class="small" role="status"></span></div></form>`}</section></div>
              <section class="card" style="margin-top:1rem" aria-labelledby="oh"><h2 id="oh">Register a hospital</h2>
                ${mine.registrations.length ? `<ul class="list" style="margin-bottom:1rem">${mine.registrations.map(r => `<li><div><span class="strong">${esc(r.hospital.name)}</span><div class="muted small">${esc(r.hospital.hospitalCode || 'Hospital ID issued on approval')} · ${S.plural(r.documents.length, 'document')}${r.decisionReason ? ' · ' + esc(r.decisionReason) : ''}</div></div><span class="row-flex">${tone(r.status)}${r.status === 'pending' ? `<label class="btn btn-sm">Add document<input type="file" hidden data-up="${esc(r.facilityId)}" accept="application/pdf,image/png,image/jpeg"></label>` : ''}</span></li>`).join('')}</ul>` : ''}
                <form id="hospReg" novalidate class="stack"><div class="grid g2">${inp('hName', 'Official hospital name', 'required minlength="3" maxlength="120"')}${sel('hType', 'Hospital type', [['Government hospital', 'Government hospital'], ['Private hospital', 'Private hospital'], ['Community health centre', 'Community health centre'], ['Clinic', 'Clinic']])}</div>
                  <div class="grid g2">${inp('hAddr', 'Address', 'required minlength="8" maxlength="240"')}${inp('hDist', 'District', 'required maxlength="40" placeholder="North Goa"')}</div>
                  <div class="grid g3">${inp('hLat', 'Latitude', 'required inputmode="decimal" placeholder="15.49"')}${inp('hLng', 'Longitude', 'required inputmode="decimal" placeholder="73.82"')}${inp('hPhone', 'Official phone', 'required maxlength="30"')}</div>
                  <div class="grid g2">${inp('hDeps', 'Departments (comma separated)', 'maxlength="400"')}${inp('hHours', 'Operating hours', 'maxlength="120" placeholder="24 hours"')}</div>
                  <div class="grid g2">${inp('hLic', 'Registration / licence number', 'required minlength="4" maxlength="60"')}${inp('hAuth', 'Issuing authority', 'required minlength="3" maxlength="100"')}</div>
                  <div class="grid g2">${inp('hEmerg', 'Emergency contact', 'maxlength="30"')}${inp('hRep', 'Authorised representative (name)', 'required minlength="2" maxlength="80"')}</div>
                  <div class="grid g3">${inp('hRepT', 'Representative role', 'maxlength="60"')}${inp('hRepP', 'Representative phone', 'maxlength="30"')}${inp('hRepE', 'Representative email', 'type="email" maxlength="120"')}</div>
                  <p class="muted small" style="margin:0">After you submit, you can attach your licence document. The hospital stays <strong>unlisted and unverified</strong> until a GoaCare administrator reviews it.</p>
                  <div class="row-flex"><button class="btn btn-primary" type="submit" ${isPatient ? '' : 'disabled'}>Submit hospital for verification</button><span id="hM" class="small" role="status"></span></div>${isPatient ? '' : '<p class="muted small">Only a personal account can submit a new hospital.</p>'}</form></section>`;
        const msg = (id, text, bad) => { const m = $('#' + id, el); if (m) { m.className = 'small' + (bad ? ' err-text' : ''); m.textContent = text; } };
        $('#redeem', el).addEventListener('submit', async e => { e.preventDefault(); try { const r = await call('POST', '/invitations/redeem', { token: val('invTok').trim() }); S.toast(r.message); setTimeout(() => { location.hash = '#/overview'; location.reload(); }, 900); } catch (err) { msg('invM', err.message, true); } });
        const dr = $('#docReg', el);
        if (dr) dr.addEventListener('submit', async e => { e.preventDefault(); try { await call('POST', '/doctors/register', { fullName: val('dName'), qualifications: val('dQual'), registrationNo: val('dReg'), issuingAuthority: val('dAuth'), specialty: val('dSpec'), department: val('dDep'), facilityId: val('dFac') || undefined }); S.toast('Submitted for verification.'); S.rerender(); } catch (err) { msg('dM', err.message, true); } });
        const up = $('#dUp', el);
        if (up) up.addEventListener('click', async () => { const f = ($('#dFile', el).files || [])[0]; if (!f) return S.toast('Choose a file first.', 'error'); try { await call('POST', '/documents', { ownerType: 'doctor', name: f.name, data: await fileToB64(f) }); S.toast('Document uploaded.'); S.rerender(); } catch (err) { S.toast(err.message, 'error'); } });
        el.querySelectorAll('[data-up]').forEach(inpt => inpt.addEventListener('change', async () => { const f = inpt.files[0]; if (!f) return; try { await call('POST', '/documents', { ownerType: 'hospital', ownerId: inpt.dataset.up, name: f.name, data: await fileToB64(f) }); S.toast('Document uploaded.'); S.rerender(); } catch (err) { S.toast(err.message, 'error'); } }));
        $('#hospReg', el).addEventListener('submit', async e => { e.preventDefault(); if (!e.target.checkValidity()) return msg('hM', 'Please complete the required fields.', true);
            try { const r = await call('POST', '/hospitals/register', { name: val('hName'), hospitalType: val('hType'), address: val('hAddr'), district: val('hDist'), lat: Number(val('hLat')), lng: Number(val('hLng')), phone: val('hPhone'), departments: val('hDeps'), operatingHours: val('hHours'), licenseNo: val('hLic'), issuingAuthority: val('hAuth'), emergencyContact: val('hEmerg'), repName: val('hRep'), repTitle: val('hRepT'), repPhone: val('hRepP'), repEmail: val('hRepE') }); S.toast(r.message); S.rerender(); } catch (err) { msg('hM', err.message, true); } });
    }
    S.register('onboarding', { title: 'Register or join', roles: ['patient', 'hospital', 'doctor'], render: (el, p) => onboarding(el, p || {}) });
    S.register('join', { title: 'Join a hospital', roles: ['patient', 'hospital', 'doctor'], render: (el, p) => onboarding(el, p || {}) });

    // ====================================================== verification (super administrator) ======================================================
    S.register('verification', { title: 'Verification', roles: ['admin'], async render(el) {
        let hs, ds;
        try { [hs, ds] = await Promise.all([call('GET', '/admin/verification/hospitals'), call('GET', '/admin/verification/doctors')]); } catch (e) { return fail(el, e); }
        const hRow = h => `<li><div><span class="strong">${esc(h.name)}</span> ${tone(h.status)} ${h.legacy ? S.badge('Existing listing - never reviewed', 'warn') : ''}<div class="muted small">${esc(h.hospitalCode || 'No Hospital ID yet')}${h.registered ? ` · licence ${esc(h.licenseNo)} (${esc(h.issuingAuthority)}) · rep ${esc(h.repName)} ${esc(h.repPhone || '')} · submitted ${esc(S.ago(h.submittedAt))}` : ''}</div>
            ${(h.documentList || []).map(d => `<a class="small" href="/api/documents/${d.id}" target="_blank" rel="noopener">${esc(d.name)}</a>`).join(' · ')}</div>
            <span class="acts">${h.status === 'pending' ? `<button class="btn btn-sm btn-primary" data-h="${esc(h.id)}" data-a="approved">Approve</button><button class="btn btn-sm btn-danger" data-h="${esc(h.id)}" data-a="rejected">Reject</button>` : ''}${h.status === 'approved' ? `<button class="btn btn-sm btn-danger" data-h="${esc(h.id)}" data-a="suspended">Suspend</button>` : ''}${h.status === 'suspended' ? `<button class="btn btn-sm btn-primary" data-h="${esc(h.id)}" data-a="approved">Reactivate</button>` : ''}</span></li>`;
        const dRow = d => `<li><div><span class="strong">${esc(d.fullName)}</span> ${tone(d.status)} ${tone(d.credentialStatus)}<div class="muted small">${esc(d.specialty)} · ${esc(d.qualifications)} · ${esc(d.issuingAuthority)} no. ${esc(d.registrationNo)} · ${esc(d.doctorCode || 'No Doctor ID yet')} · ${esc(d.login)}${d.affiliations.length ? ' · ' + d.affiliations.map(a => esc(a.facilityName) + ' (' + esc(a.status.replace(/_/g, ' ')) + ')').join(', ') : ''}</div></div>
            <span class="acts">${d.status === 'pending' ? `<button class="btn btn-sm btn-primary" data-d="${d.id}" data-a="approve">Check &amp; approve</button><button class="btn btn-sm btn-danger" data-d="${d.id}" data-a="reject">Reject</button>` : ''}</span></li>`;
        el.innerHTML = S.head('Verification', 'Review hospital registrations and doctors. Nothing is verified automatically: no official registry is connected, so you record the result of your own check.')
            + note('Existing hospitals were imported before verification existed. They are shown to patients but remain <strong>unverified</strong> until you approve them here.', 'warn')
            + `<section class="card" aria-labelledby="vh"><h2 id="vh">Hospitals</h2><div class="row-flex" style="margin-bottom:.6rem"><label class="lbl" for="vf">Show</label><select id="vf" class="in" style="max-width:12rem"><option value="pending">Pending</option><option value="">All</option><option value="approved">Approved</option><option value="suspended">Suspended</option><option value="rejected">Rejected</option></select></div><ul class="list" id="hl"></ul></section>
               <section class="card" style="margin-top:1rem" aria-labelledby="vd"><h2 id="vd">Doctor registrations</h2><ul class="list">${ds.doctors.length ? ds.doctors.map(dRow).join('') : '<li class="muted">No doctor registrations yet.</li>'}</ul></section>`;
        const drawH = () => { const f = val('vf'); const list = hs.hospitals.filter(h => !f || h.status === f); $('#hl', el).innerHTML = list.length ? list.slice(0, 80).map(hRow).join('') : '<li class="muted">Nothing here.</li>'; if (list.length > 80) $('#hl', el).insertAdjacentHTML('beforeend', `<li class="muted small">Showing 80 of ${list.length}. Use the filter to narrow the list.</li>`); };
        $('#vf', el).addEventListener('change', drawH); drawH();
        el.addEventListener('click', async ev => {
            const b = ev.target.closest('button[data-a]'); if (!b) return;
            if (b.dataset.h) {
                const to = b.dataset.a, needReason = to !== 'approved' || b.textContent === 'Reactivate', needPw = to === 'suspended' || b.textContent === 'Reactivate';
                await asked(to === 'approved' ? (needPw ? 'Reactivate hospital' : 'Approve hospital') : to === 'rejected' ? 'Reject registration' : 'Suspend hospital', 'Reason (kept in the audit history)', { reason: true, reasonRequired: needReason, password: needPw, danger: to !== 'approved', submit: 'Confirm',
                    text: to === 'approved' && !needPw ? 'Approving issues a permanent Hospital ID and lists the hospital as verified. Only approve after checking its licence.' : undefined,
                    run: async v => { await call('PUT', `/admin/hospitals/${encodeURIComponent(b.dataset.h)}/status`, { status: to, reason: v.reason || undefined, password: v.password || undefined }); } }) && (S.toast('Saved.'), S.rerender());
            } else {
                const reject = b.dataset.a === 'reject';
                await S.modal({ title: reject ? 'Reject doctor registration' : 'Check and approve doctor', submit: reject ? 'Reject' : 'Approve and issue Doctor ID', danger: reject,
                    body: reject ? field('xr', 'Reason', '<textarea id="xr" name="reason" class="in" rows="3" required minlength="5"></textarea>')
                        : `<p>Look up the registration number on the official register of the issuing authority. Tick the box only if you did.</p><label class="row-flex"><input type="checkbox" name="ok" required> <span>I checked this registration number against the official register.</span></label>${field('xn', 'What you checked (shown in the audit history)', '<input id="xn" name="note" class="in" required minlength="5" maxlength="300" placeholder="e.g. Goa Medical Council online register, 12 Oct 2026">')}`,
                    onSubmit: async (d, f) => { await call('PUT', `/admin/doctors/${b.dataset.d}/decision`, reject ? { decision: 'reject', reason: f.get('reason') } : { decision: 'approve', credentialsVerified: true, credentialNote: f.get('note') }); S.toast('Saved.'); S.rerender(); } });
            }
        });
    } });

    // ====================================================== staff & access ======================================================
    S.register('staffing', { title: 'Staff & Access', roles: ['hospital', 'admin'], cap: 'invites', async render(el) {
        if (S.needFacility(el)) return;
        let inv, aff, team;
        try { [inv, aff, team] = await Promise.all([call('GET', q('/staff/invitations')), call('GET', q('/staff/affiliations')), call('GET', q('/staff/team'))]); } catch (e) { return fail(el, e); }
        const can = S.can('invites', 'write');
        const roles = inv.roles.filter(r => r !== 'manager' || S.user.role === 'admin');
        el.innerHTML = S.head('Staff & Access', 'Invite colleagues with a one-time link, verify doctors who want to join, and switch access off when someone leaves.')
            + (can ? `<section class="card stack" aria-labelledby="si"><h2 id="si">Invite someone</h2><form id="invForm" class="grid g3" novalidate>${inp('iRec', 'Their email or mobile number / Health ID', 'required maxlength="120"', 'The link only works for this person.')}${sel('iRole', 'Role', roles.map(r => [r, ROLE[r] || r]))}<div class="field"><label class="lbl">&nbsp;</label><button class="btn btn-primary" type="submit">Create invitation</button></div></form><p class="muted small" style="margin:0">Links expire after ${inv.ttlHours} hours and work once. To make someone an administrator of this hospital, ask the GoaCare team, or use "Team roles" in Settings (another administrator must approve).</p><div id="invOut"></div></section>` : '')
            + `<section class="card" style="margin-top:1rem" aria-labelledby="sv"><h2 id="sv">Invitations</h2><ul class="list" id="invList"></ul></section>
               <section class="card" style="margin-top:1rem" aria-labelledby="sa"><h2 id="sa">Doctors at this hospital</h2><ul class="list">${aff.affiliations.length ? aff.affiliations.map(a => `<li><div><span class="strong">${esc(a.doctorName || 'Doctor #' + a.userId)}</span> ${tone(a.status)}<div class="muted small">${esc(a.doctorCode || 'Doctor ID issued after approval')} · requested ${esc(S.ago(a.requestedAt))}</div></div><span class="acts">${a.status === 'requested' ? `<button class="btn btn-sm btn-primary" data-af="${a.id}" data-a="verify">Confirm affiliation</button><button class="btn btn-sm btn-danger" data-af="${a.id}" data-a="reject">Decline</button>` : ''}${a.status !== 'requested' && can ? `<button class="btn btn-sm btn-danger" data-af="${a.id}" data-a="end">End affiliation</button>` : ''}</span></li>`).join('') : '<li class="muted">No doctor affiliations yet.</li>'}</ul><p class="muted small" style="margin-bottom:0">Confirming an affiliation says this doctor works here. GoaCare separately checks their professional registration before they are verified.</p></section>
               <section class="card" style="margin-top:1rem" aria-labelledby="st"><h2 id="st">Staff accounts</h2><ul class="list">${team.team.map(m => `<li><div><span class="strong">${esc(m.name)}</span>${m.id === S.user.id ? ' ' + S.badge('You', 'brand') : ''} ${S.badge(ROLE[m.staffRole] || m.staffRole, 'info')} ${m.active === false ? S.badge('Deactivated', 'bad') : ''}<div class="muted small">${esc(m.login)}</div></div><span class="acts">${can && m.id !== S.user.id ? (m.active === false ? `<button class="btn btn-sm" data-ac="${m.id}" data-a="reactivate">Reactivate</button>` : `<button class="btn btn-sm btn-danger" data-ac="${m.id}" data-a="deactivate">Deactivate</button>`) + `<button class="btn btn-sm btn-danger" data-ac="${m.id}" data-a="remove">Remove from hospital</button>` : ''}</span></li>`).join('')}</ul></section>`;
        const drawInv = () => { $('#invList', el).innerHTML = inv.invitations.length ? inv.invitations.map(i => `<li><div><span class="strong">${esc(ROLE[i.role] || i.role)}</span> ${tone(i.status)}<div class="muted small">${esc(i.recipient)} · created ${esc(S.ago(i.createdAt))} · expires ${esc(S.fmtStamp(i.expiresAt))}</div></div><span class="acts">${can && i.status === 'pending' ? `<button class="btn btn-sm btn-danger" data-iv="${i.id}" data-a="revoke">Revoke</button>` : ''}${can && ['pending', 'expired', 'revoked'].includes(i.status) ? `<button class="btn btn-sm" data-iv="${i.id}" data-a="regenerate">New link</button>` : ''}</span></li>`).join('') : '<li class="muted">No invitations yet.</li>'; };
        drawInv();
        const showLink = r => { const url = location.origin + r.link; $('#invOut', el).innerHTML = note(`Copy this link now - it cannot be shown again: <input class="in" readonly value="${esc(url)}" onfocus="this.select()" aria-label="Invitation link" style="margin-top:.4rem">`, 'ok'); };
        const f = $('#invForm', el);
        if (f) f.addEventListener('submit', async e => { e.preventDefault(); try { const r = await call('POST', q('/staff/invitations'), { recipient: val('iRec'), role: val('iRole') }); showLink(r); inv = await call('GET', q('/staff/invitations')); drawInv(); f.reset(); } catch (err) { S.toast(err.message, 'error'); } });
        el.addEventListener('click', async ev => {
            const b = ev.target.closest('button[data-a]'); if (!b) return;
            try {
                if (b.dataset.iv) { const r = await call('PUT', `/staff/invitations/${b.dataset.iv}` + (fq() ? '?' + fq() : ''), { action: b.dataset.a }); if (r.token) showLink(r); S.toast(b.dataset.a === 'revoke' ? 'Invitation revoked.' : 'New link created.'); inv = await call('GET', q('/staff/invitations')); drawInv(); }
                else if (b.dataset.af) { const a = b.dataset.a; if (a === 'verify') { await call('PUT', `/staff/affiliations/${b.dataset.af}`, { action: 'verify' }); S.toast('Affiliation confirmed.'); S.rerender(); } else await asked(a === 'end' ? 'End affiliation' : 'Decline request', 'Reason', { reason: true, reasonRequired: true, danger: true, run: v => call('PUT', `/staff/affiliations/${b.dataset.af}`, { action: a, reason: v.reason }) }) && (S.toast('Saved.'), S.rerender()); }
                else if (b.dataset.ac) { const a = b.dataset.a; await asked({ deactivate: 'Deactivate account', reactivate: 'Reactivate account', remove: 'Remove from hospital' }[a], 'Reason', { reason: a !== 'reactivate', reasonRequired: a !== 'reactivate', danger: a !== 'reactivate', text: a === 'reactivate' ? undefined : 'Access stops immediately. All past activity stays in the audit history.', run: v => call('PUT', `/staff/team/${b.dataset.ac}/access`, { action: a, reason: v.reason || undefined }) }) && (S.toast('Saved.'), S.rerender()); }
            } catch (err) { S.toast(err.message, 'error'); }
        });
    } });

    // ====================================================== medicine inventory ======================================================
    S.register('inventory', { title: 'Medicine Inventory', roles: ['hospital'], cap: 'inventory', async render(el) {
        let d;
        try { d = await call('GET', '/staff/inventory'); } catch (e) { return fail(el, e); }
        const w = S.can('inventory', 'write');
        el.innerHTML = S.head('Medicine Inventory', 'Internal stock. Patients only see "in stock / low / out" for items you choose to publish - never quantities.', w ? '<button class="btn btn-primary" id="mAdd"><i class="fa-solid fa-plus" aria-hidden="true"></i> Add medicine</button>' : '')
            + (d.publicAvailabilityLive ? '' : note('Public medicine availability is switched on only after GoaCare verifies this hospital.', 'warn'))
            + `<div id="mTbl"></div><section class="card" style="margin-top:1rem"><h2>Recent stock changes</h2><div id="mHist">${S.loading()}</div></section>`;
        const draw = () => S.table($('#mTbl', el), { pageSize: 10, sort: { key: 'name', dir: 1 }, empty: 'No medicines yet.', rows: d.items,
            cols: [{ key: 'name', label: 'Medicine', sort: true, html: r => `<span class="strong">${esc(r.name)}</span> ${esc(r.strength)}` }, { key: 'quantity', label: 'In stock', sort: true, html: r => `${r.quantity} ${esc(r.unit)}` }, { key: 'reorderLevel', label: 'Re-order at', sort: true, html: r => String(r.reorderLevel) }, { key: 'availability', label: 'Status', sort: true, html: r => tone(r.availability) }, { key: 'publish', label: 'Shown to patients', html: r => (r.publish ? S.badge('Published', 'ok') : S.badge('Internal only', 'mute')) }, { key: 'updatedAt', label: 'Updated', sort: true, html: r => esc(S.ago(r.updatedAt)) },
                { key: 'a', label: 'Actions', actions: true, html: r => w ? `<span class="acts"><button class="btn btn-sm" data-adj="${r.id}">Adjust stock</button><button class="btn btn-sm" data-ed="${r.id}">Edit</button></span>` : '' }] });
        const hist = async () => { try { const h = await call('GET', '/staff/inventory/history?limit=30'); $('#mHist', el).innerHTML = h.history.length ? `<ul class="list">${h.history.map(x => `<li><div><span class="strong">${esc(x.item)}</span> <span class="${x.delta < 0 ? 'err-text' : ''}">${x.delta > 0 ? '+' : ''}${x.delta}</span> <span class="muted small">(${x.before} → ${x.after})</span><div class="muted small">${esc(x.reason)} · ${esc(x.by)} · ${esc(S.fmtStamp(x.at))}</div></div></li>`).join('')}</ul>` : '<p class="muted">No changes recorded yet.</p>'; } catch (e) { $('#mHist', el).innerHTML = ''; } };
        const reload = async () => { d = await call('GET', '/staff/inventory'); draw(); hist(); };
        draw(); hist();
        const form = (m) => `${inp('fN', 'Medicine name', 'name="name" required maxlength="100" value="' + esc(m ? m.name : '') + '"')}<div class="grid g2">${inp('fS', 'Strength', 'name="strength" maxlength="40" value="' + esc(m ? m.strength : '') + '"')}${inp('fU', 'Unit', 'name="unit" maxlength="20" value="' + esc(m ? m.unit : 'tablets') + '"')}</div><div class="grid g2">${m ? '' : inp('fQ', 'Opening quantity', 'name="quantity" type="number" min="0" step="1" required value="0"')}${inp('fR', 'Re-order level', 'name="reorderLevel" type="number" min="0" step="1" required value="' + (m ? m.reorderLevel : 10) + '"')}</div><label class="row-flex"><input type="checkbox" name="publish" ${m && m.publish ? 'checked' : ''}> <span>Show in-stock / low / out to patients</span></label>`;
        const grab = f => ({ name: f.get('name'), strength: f.get('strength') || '', unit: f.get('unit') || 'units', quantity: f.get('quantity') == null ? undefined : Number(f.get('quantity')), reorderLevel: Number(f.get('reorderLevel')), publish: f.get('publish') === 'on' });
        if (w) $('#mAdd', el).addEventListener('click', async () => { if (await S.modal({ title: 'Add medicine', body: form(null), onSubmit: async (dlg, f) => { await call('POST', '/staff/inventory', grab(f)); } })) { S.toast('Added.'); reload(); } });
        el.addEventListener('click', async ev => {
            const a = ev.target.closest('[data-adj]'), e = ev.target.closest('[data-ed]');
            if (a) { const m = d.items.find(x => x.id === Number(a.dataset.adj)); if (await S.modal({ title: 'Adjust stock: ' + m.name, submit: 'Record change', body: `<p>Currently <strong>${m.quantity} ${esc(m.unit)}</strong>. Use a negative number for stock going out.</p>${inp('aD', 'Change', 'name="delta" type="number" step="1" required placeholder="e.g. 50 or -10"')}${inp('aR', 'Reason', 'name="reason" required minlength="3" maxlength="200" placeholder="e.g. Delivery received, ward issue, expired"')}`, onSubmit: async (dlg, f) => { await call('POST', `/staff/inventory/${m.id}/adjust`, { delta: Number(f.get('delta')), reason: f.get('reason') }); } })) { S.toast('Stock updated.'); reload(); } }
            if (e) { const m = d.items.find(x => x.id === Number(e.dataset.ed)); try { if (await S.modal({ title: 'Edit ' + m.name, body: form(m), onSubmit: async (dlg, f) => { await call('PUT', `/staff/inventory/${m.id}`, { ...grab(f), expectedVersion: m.version }); } })) { S.toast('Saved.'); reload(); } } catch (err) { S.toast(err.message, 'error'); } }
        });
    } });

    // ====================================================== approvals ======================================================
    S.register('approvals', { title: 'Approvals', roles: ['hospital', 'admin'], cap: 'approvals', async render(el) {
        if (S.needFacility(el)) return;
        let d;
        try { d = await call('GET', q('/staff/approvals')); } catch (e) { return fail(el, e); }
        const pend = d.approvals.filter(a => a.status === 'pending'), done = d.approvals.filter(a => a.status !== 'pending');
        const row = a => `<li><div><span class="strong">${esc(a.summary)}</span> ${tone(a.status)}<div class="muted small">Requested by ${esc(a.requestedByName || '#' + a.requestedBy)} · ${esc(S.ago(a.requestedAt))}${a.decisionReason ? ' · ' + esc(a.decisionReason) : ''}</div>${a.current ? `<div class="muted small">Current: ${esc(JSON.stringify(a.current))}</div>` : ''}</div><span class="acts">${a.canDecide ? `<button class="btn btn-sm btn-primary" data-id="${a.id}" data-k="${esc(a.kind)}" data-a="approve">Approve</button><button class="btn btn-sm btn-danger" data-id="${a.id}" data-k="${esc(a.kind)}" data-a="reject">Reject</button>` : a.status === 'pending' ? '<span class="muted small">Waiting for another administrator</span>' : ''}</span></li>`;
        el.innerHTML = S.head('Approvals', 'High-impact changes wait here. Published information stays as it is until a different administrator approves.')
            + `<section class="card" aria-labelledby="ap"><h2 id="ap">Waiting for a decision</h2><ul class="list">${pend.length ? pend.map(row).join('') : '<li class="muted">Nothing is waiting.</li>'}</ul></section><section class="card" style="margin-top:1rem"><h2>Decided</h2><ul class="list">${done.length ? done.map(row).join('') : '<li class="muted">No decisions yet.</li>'}</ul></section>`;
        el.addEventListener('click', async ev => {
            const b = ev.target.closest('button[data-a]'); if (!b) return;
            const ap = b.dataset.a === 'approve', pw = ap && b.dataset.k === 'role_assignment';
            if (await asked(ap ? 'Approve change' : 'Reject change', 'Reason', { reason: true, reasonRequired: !ap, password: pw, danger: !ap, text: pw ? 'Making someone a hospital administrator gives them full control of this hospital.' : undefined, run: v => call('POST', `/staff/approvals/${b.dataset.id}/decision`, { decision: b.dataset.a, reason: v.reason || undefined, password: v.password || undefined }) })) { S.toast('Decision recorded.'); S.refreshAlerts(); S.rerender(); }
        });
    } });

    // ====================================================== reports ======================================================
    S.register('reports', { title: 'Reports', roles: ['hospital', 'admin'], cap: 'reports', async render(el) {
        let list;
        try { list = (await call('GET', '/reports')).reports; } catch (e) { return fail(el, e); }
        const global = list.filter(r => !r.needsHospital), needs = list.filter(r => r.needsHospital);
        el.innerHTML = S.head('Reports', 'Built from the stored records of your hospital only.')
            + `<div class="filters row-flex" style="margin-bottom:1rem">${field('rN', 'Report', `<select id="rN" class="in">${list.map(r => `<option value="${r.name}">${esc(r.title)}</option>`).join('')}</select>`)}${field('rF', 'From', '<input id="rF" type="date" class="in">')}${field('rT', 'To', '<input id="rT" type="date" class="in">')}<div class="field"><label class="lbl">&nbsp;</label><span class="row-flex"><button class="btn btn-primary" id="rGo">Show</button><button class="btn" id="rCsv">Download CSV</button></span></div></div><div id="rOut" class="card"><p class="muted" style="margin:0">Choose a report.</p></div>`;
        const url = fmt => { const r = list.find(x => x.name === val('rN')); return `/api/reports/${val('rN')}?` + [r && r.needsHospital ? fq() : '', val('rF') && 'from=' + val('rF'), val('rT') && 'to=' + val('rT'), fmt].filter(Boolean).join('&'); };
        const need = () => { const r = list.find(x => x.name === val('rN')); return r && r.needsHospital && S.user.role === 'admin' && !S.facilityId; };
        $('#rGo', el).addEventListener('click', async () => { if (need()) return S.toast('Choose a hospital at the top first.', 'error'); const o = $('#rOut', el); o.innerHTML = S.loading(); try { const r = await call('GET', url('').replace('/api', '')); o.innerHTML = `<h2>${esc(r.title)}${r.hospital ? ' · ' + esc(r.hospital) : ''}</h2><p class="muted small">Generated ${esc(S.fmtStamp(r.generatedAt))}</p>` + (r.rows.length ? `<div class="tbl-wrap"><table class="tbl"><thead><tr>${r.columns.map(c => `<th scope="col">${esc(c)}</th>`).join('')}</tr></thead><tbody>${r.rows.slice(0, 300).map(x => `<tr>${x.map((c, i) => `<td data-label="${esc(r.columns[i])}">${esc(c == null ? '' : c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${r.rows.length > 300 ? '<p class="muted small">Showing the first 300 rows. Download the CSV for everything.</p>' : ''}` : '<p class="muted">No records in this period.</p>'); } catch (e) { o.innerHTML = S.errorBox(e.message); } });
        $('#rCsv', el).addEventListener('click', () => { if (need()) return S.toast('Choose a hospital at the top first.', 'error'); location.href = url('format=csv'); });
    } });

    // ====================================================== audit history (read only) ======================================================
    S.register('audit', { title: 'Audit History', roles: ['hospital', 'doctor', 'admin'], async render(el) {
        let off = 0, data, integ;
        const LIM = 20, f = { q: '', action: '', outcome: '', from: '', to: '', facilityId: '' };
        const qs = (extra) => new URLSearchParams(Object.assign({}, Object.fromEntries(Object.entries(f).filter(([, v]) => v)), extra || {})).toString();
        try { integ = await call('GET', '/audit/integrity'); data = await call('GET', '/audit/events?' + qs({ limit: LIM, offset: 0 })); } catch (e) { return fail(el, e); }
        const v = integ.latestVerification;
        const status = () => v ? (v.ok ? S.badge('Chain verified ' + S.ago(v.ranAt), 'ok') : S.badge('Integrity problems found ' + S.ago(v.ranAt), 'bad')) : S.badge('Never verified', 'warn');
        el.innerHTML = S.head('Audit History', 'A permanent, read-only record of important actions. Entries cannot be edited or deleted by anyone, including administrators.', `<a class="btn" id="aExp" href="#"><i class="fa-solid fa-file-csv" aria-hidden="true"></i> Export CSV</a>${integ.canVerify ? '<button class="btn btn-primary" id="aVer">Verify integrity now</button>' : ''}`)
            + `<section class="card" aria-labelledby="ai"><h2 id="ai">Integrity</h2><div class="row-flex">${status()}<span class="muted small">${v ? S.plural(v.eventsChecked, 'event') + ' checked' : ''}</span></div>
                ${v && !v.ok ? `<ul class="list">${v.problems.slice(0, 5).map(p => `<li class="err-text">${esc(p.type.replace(/_/g, ' '))}${p.seq ? ' at event ' + p.seq : ''}: ${esc(p.detail || '')}</li>`).join('')}</ul>` : ''}
                <p class="muted small" style="margin:.5rem 0 0">Each entry is linked to the one before it by a cryptographic hash, so a changed, removed or reordered entry is detected. Checkpoints: ${integ.latestCheckpoint ? esc(S.fmtStamp(integ.latestCheckpoint.at)) + (integ.signedCheckpoints ? ' (signed)' : ' (unsigned)') : 'none yet'}. Backups: ${esc(integ.backup.note)}</p>
                ${integ.alerts.length ? `<h3 style="margin:.6rem 0 .2rem">Unresolved security alerts</h3><ul class="list">${integ.alerts.map(a => `<li><span>${esc(a.summary)} <span class="muted small">${esc(S.ago(a.createdAt))}</span></span></li>`).join('')}</ul>` : ''}</section>
              <form class="filters row-flex" id="aF" style="margin:1rem 0" novalidate>${field('fQ', 'Search', '<input id="fQ" class="in" placeholder="Action, record, reason…">')}${field('fA', 'Action', `<select id="fA" class="in"><option value="">All actions</option>${data.actions.map(a => `<option>${esc(a)}</option>`).join('')}</select>`)}${field('fO', 'Outcome', '<select id="fO" class="in"><option value="">All</option><option value="success">Success</option><option value="failure">Failure</option><option value="blocked">Blocked</option></select>')}${field('fFr', 'From', '<input id="fFr" type="date" class="in">')}${field('fTo', 'To', '<input id="fTo" type="date" class="in">')}${S.user.role === 'admin' ? field('fH', 'Hospital', `<select id="fH" class="in"><option value="">All hospitals</option>${S.facilities.map(x => `<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('')}</select>`) : ''}<div class="field"><label class="lbl">&nbsp;</label><button class="btn btn-primary" type="submit">Filter</button></div></form>
              <p class="muted small" id="aScope"></p><div id="aList"></div><div class="row-flex" id="aPg" style="justify-content:space-between;margin-top:.8rem"></div>
              <section class="card" style="margin-top:1rem"><h2>Report suspected tampering</h2><form id="aRep" class="row-flex" novalidate>${field('rD', 'What did you notice?', '<input id="rD" class="in" required minlength="10" maxlength="800" style="min-width:20rem">')}<div class="field"><label class="lbl">&nbsp;</label><button class="btn" type="submit">Send report</button></div></form></section>`;
        const draw = () => {
            $('#aScope', el).textContent = `Showing ${data.scope}. ${data.total} event${data.total === 1 ? '' : 's'}.`;
            $('#aList', el).innerHTML = data.items.length ? `<div class="tbl-wrap"><table class="tbl"><thead><tr><th scope="col">Time</th><th scope="col">Action</th><th scope="col">Who</th><th scope="col">Record</th><th scope="col">Outcome</th><th scope="col"><span class="sr-only">Details</span></th></tr></thead><tbody>${data.items.map(e => `<tr><td data-label="Time">${esc(S.fmtStamp(e.at))}</td><td data-label="Action"><span class="strong">${esc(e.action.replace(/_/g, ' '))}</span></td><td data-label="Who">${esc(e.actorRole)}${e.actorId ? ' #' + e.actorId : ''}</td><td data-label="Record">${esc(e.resourceType)}${e.resourceId ? ' ' + esc(e.resourceId) : ''}</td><td data-label="Outcome">${tone(e.outcome)}</td><td><button class="btn btn-sm" data-ev="${esc(e.id)}">Details</button></td></tr>`).join('')}</tbody></table></div>` : S.empty({ icon: 'fa-clock-rotate-left', title: 'No matching events', text: 'Try widening the filters.' });
            const pages = Math.max(1, Math.ceil(data.total / LIM)), cur = Math.floor(off / LIM) + 1;
            $('#aPg', el).innerHTML = `<span class="muted small">Page ${cur} of ${pages}</span><span class="row-flex"><button class="btn btn-sm" id="pPrev" ${off === 0 ? 'disabled' : ''}>Previous</button><button class="btn btn-sm" id="pNext" ${off + LIM >= data.total ? 'disabled' : ''}>Next</button></span>`;
        };
        const load = async () => { $('#aList', el).innerHTML = S.loading(); try { data = await call('GET', '/audit/events?' + qs({ limit: LIM, offset: off })); draw(); } catch (e) { $('#aList', el).innerHTML = S.errorBox(e.message); } };
        draw();
        $('#aF', el).addEventListener('submit', e => { e.preventDefault(); Object.assign(f, { q: val('fQ'), action: val('fA'), outcome: val('fO'), from: val('fFr'), to: val('fTo'), facilityId: val('fH') }); off = 0; load(); });
        $('#aExp', el).addEventListener('click', e => { e.preventDefault(); location.href = '/api/audit/export?' + qs(); });
        const ver = $('#aVer', el); if (ver) ver.addEventListener('click', async () => { ver.disabled = true; try { const r = (await call('POST', '/audit/verify', {})).result; S.toast(r.ok ? 'The audit chain is intact.' : 'Integrity problems were found.', r.ok ? undefined : 'error'); S.rerender(); } catch (e) { S.toast(e.message, 'error'); ver.disabled = false; } });
        $('#aRep', el).addEventListener('submit', async e => { e.preventDefault(); if (!e.target.checkValidity()) return S.toast('Please describe what you saw (at least 10 characters).', 'error'); try { const r = await call('POST', '/audit/report', { description: val('rD') }); S.toast(r.message); e.target.reset(); } catch (err) { S.toast(err.message, 'error'); } });
        el.addEventListener('click', async ev => {
            if (ev.target.id === 'pPrev') { off = Math.max(0, off - LIM); return load(); }
            if (ev.target.id === 'pNext') { off += LIM; return load(); }
            const b = ev.target.closest('[data-ev]'); if (!b) return;
            try {
                const e = (await call('GET', '/audit/events/' + encodeURIComponent(b.dataset.ev))).event, keys = [...new Set([...Object.keys(e.before || {}), ...Object.keys(e.after || {})])];
                S.modal({ title: e.action.replace(/_/g, ' '), hideSubmit: true, cancel: 'Close', wide: true, body: dl([['When', S.fmtStamp(e.at)], ['Who', e.actorRole + (e.actorId ? ' #' + e.actorId : '')], ['Hospital', e.facilityId], ['Record', e.resourceType + (e.resourceId ? ' ' + e.resourceId : '')], ['Outcome', tone(e.outcome), 1], ['Reason', e.reason], ['Request ID', e.requestId]])
                    + (keys.length ? `<h3>Before and after</h3><div class="tbl-wrap"><table class="tbl"><thead><tr><th scope="col">Field</th><th scope="col">Before</th><th scope="col">After</th></tr></thead><tbody>${keys.map(k => { const a = (e.before || {})[k], b2 = (e.after || {})[k]; return `<tr><td>${esc(k)}</td><td>${esc(a == null ? '-' : typeof a === 'object' ? JSON.stringify(a) : a)}</td><td ${JSON.stringify(a) !== JSON.stringify(b2) ? 'class="strong"' : ''}>${esc(b2 == null ? '-' : typeof b2 === 'object' ? JSON.stringify(b2) : b2)}</td></tr>`; }).join('')}</tbody></table></div>` : '')
                    + (Object.keys(e.detail || {}).length ? `<h3>Details</h3><pre class="small" style="white-space:pre-wrap;overflow:auto">${esc(JSON.stringify(e.detail, null, 2))}</pre>` : '')
                    + `<p class="muted small" style="word-break:break-all">Entry ${e.seq} · hash ${esc(e.hash)}<br>previous ${esc(e.prevHash)}</p>` });
            } catch (err) { S.toast(err.message, 'error'); }
        });
    } });

    // ====================================================== settings: extra sections added to the existing page ======================================================
    const baseSettings = S.pages.settings;
    S.register('settings', Object.assign({}, baseSettings, { async render(el, p) {
        // The existing page asks for the team list, which an administrator without a chosen hospital cannot have: keep the page usable anyway.
        try { await baseSettings.render(el, p); } catch (e) { const t = el.querySelector('#team'); if (t) t.innerHTML = `<p class="muted small">Choose a hospital at the top to manage its team.</p>`; }
        const host = document.createElement('div'); host.id = 'govSettings'; host.style.marginTop = '1rem'; host.innerHTML = S.loading('Loading more settings…'); el.appendChild(host);
        try {
            const [prof, sec, notif, help, integ] = await Promise.all([call('GET', '/settings/profile'), call('GET', '/settings/security'), call('GET', '/settings/notifications'), call('GET', '/settings/help'), call('GET', '/audit/integrity')]);
            const pr = prof.profile;
            host.innerHTML = `<div class="grid g2">
              <form class="card stack" id="sProf" novalidate aria-label="My profile"><h2>My profile</h2>${inp('spN', 'Name', 'required minlength="2" maxlength="80" value="' + esc(pr.name) + '"')}${inp('spE', 'Email', 'type="email" maxlength="120" value="' + esc(pr.email || '') + '"')}
                ${dl([['Sign-in ID', pr.login], ['Role', pr.role === 'hospital' ? ROLE[pr.staffRole] || pr.staffRole : pr.role === 'doctor' ? 'Doctor' : 'GoaCare administrator'], pr.facility && ['Hospital', `${pr.facility.name}${pr.facility.hospitalCode ? ' (' + pr.facility.hospitalCode + ')' : ''}`], pr.doctor && ['Doctor ID', pr.doctor.doctorCode || 'Issued after approval']])}
                <p class="muted small" style="margin:0">Your role, hospital and verification status can only be changed by an administrator. ${esc(prof.photo.note)}</p><div class="row-flex"><button class="btn btn-primary" type="submit">Save profile</button></div></form>
              <section class="card stack" aria-labelledby="sn"><h2 id="sn">Notifications</h2><ul class="list">${notif.preferences.map(n => `<li><label class="row-flex"><input type="checkbox" data-pref="${n.key}" ${n.enabled ? 'checked' : ''} ${n.mandatory ? 'disabled' : ''}> <span>${esc(n.label)}${n.mandatory ? ' <span class="muted small">(required)</span>' : ''}</span></label></li>`).join('')}</ul></section></div>
              <section class="card" style="margin-top:1rem" aria-labelledby="ss"><h2 id="ss">Security and sign-in</h2>
                <div class="grid g2"><div><h3>Signed-in devices</h3><ul class="list">${sec.sessions.map(s => `<li><div><span class="strong">${esc((s.device || 'Unknown device').slice(0, 60))}</span> ${s.current ? S.badge('This device', 'brand') : ''}<div class="muted small">${esc(s.ip || '')} · since ${esc(s.createdAt ? S.ago(s.createdAt) : 'earlier')}</div></div>${s.current ? '' : `<button class="btn btn-sm" data-rs="${esc(s.handle)}">Sign out</button>`}</li>`).join('')}</ul><button class="btn" id="sOut" ${sec.sessions.length < 2 ? 'disabled' : ''}>Sign out of all other devices</button></div>
                <div><h3>Recent sign-ins</h3><ul class="list">${sec.recentLogins.map(l => `<li><span>${l.ok ? S.badge('Signed in', 'ok') : S.badge('Failed attempt', 'bad')} <span class="muted small">${esc(S.fmtStamp(l.at))}</span></span></li>`).join('') || '<li class="muted">None yet.</li>'}</ul>${sec.alerts.length ? `<h3>Blocked actions on your account</h3><ul class="list">${sec.alerts.map(a => `<li class="small">${esc(S.fmtStamp(a.at))}: ${esc(a.action.replace(/_/g, ' '))}</li>`).join('')}</ul>` : ''}</div></div>
                <p class="muted small" style="margin-bottom:0">${esc(sec.mfa.note)} ${esc(sec.password.resetNote)}</p></section>
              <section class="card" style="margin-top:1rem" aria-labelledby="sa2"><h2 id="sa2">Audit and data integrity</h2><div class="row-flex"><a class="btn" href="#/audit">Open Audit History</a>${integ.latestVerification ? (integ.latestVerification.ok ? S.badge('Last check passed ' + S.ago(integ.latestVerification.ranAt), 'ok') : S.badge('Last check found problems', 'bad')) : S.badge('Never verified', 'warn')}${integ.alerts.length ? S.badge(S.plural(integ.alerts.length, 'open alert'), 'warn') : ''}</div><p class="muted small" style="margin-bottom:0">${esc(integ.backup.note)}</p></section>
              <section class="card" style="margin-top:1rem" aria-labelledby="sh"><h2 id="sh">Help and support</h2>${dl([['App version', help.version], ['Support', help.support || 'Not configured by this deployment'], ['Privacy policy', help.privacyPolicyUrl ? `<a href="${esc(help.privacyPolicyUrl)}" rel="noopener">${esc(help.privacyPolicyUrl)}</a>` : 'Not configured by this deployment', 1], ['Security issues', help.securityContact || 'Use "Report suspected tampering" on the Audit History page']])}<p class="muted small" style="margin-bottom:0">${esc(help.bugReports)}</p></section>`;
            $('#sProf', host).addEventListener('submit', async e => { e.preventDefault(); try { await call('PUT', '/settings/profile', { name: val('spN'), email: val('spE') }); S.toast('Profile saved.'); } catch (err) { S.toast(err.message, 'error'); } });
            host.addEventListener('change', async e => { const k = e.target.dataset && e.target.dataset.pref; if (!k) return; try { await call('PUT', '/settings/notifications', { preferences: { [k]: e.target.checked } }); S.toast('Saved.'); S.refreshAlerts(); } catch (err) { e.target.checked = !e.target.checked; S.toast(err.message, 'error'); } });
            host.addEventListener('click', async e => { const r = e.target.closest('[data-rs]'); try { if (r) { await call('DELETE', '/settings/sessions/' + encodeURIComponent(r.dataset.rs)); S.toast('Signed out.'); S.rerender(); } else if (e.target.id === 'sOut') { const o = await call('POST', '/settings/sessions/revoke-others', {}); S.toast(`Signed out of ${S.plural(o.revoked, 'device')}.`); S.rerender(); } } catch (err) { S.toast(err.message, 'error'); } });
        } catch (err) { host.innerHTML = S.errorBox(err.message); }
    } }));

    // ====================================================== overview: show verification state at the top ======================================================
    const baseOverview = S.pages.overview;
    S.register('overview', Object.assign({}, baseOverview, { async render(el, p) {
        let o = null;
        if (S.user.role === 'hospital') { try { o = await call('GET', '/staff/overview'); } catch (e) { o = null; } }
        if (o && o.restricted) {   // pharmacy and finance staff get a focused workspace, not the clinical overview
            const g = o.governance, h = g.hospital;
            el.innerHTML = S.head('Overview', o.facility.name)
                + `<div class="notice n-${h.trusted ? 'ok' : 'info'}" style="margin-bottom:1rem"><i class="fa-solid ${h.trusted ? 'fa-circle-check' : 'fa-circle-info'}" aria-hidden="true"></i><span><strong>${h.trusted ? 'Verified by GoaCare' : 'Not verified yet'}</strong>${h.hospitalCode ? ' · Hospital ID ' + esc(h.hospitalCode) : ''}</span></div>`
                + `<div class="grid g3">${o.restricted.includes('inventory') ? `<a class="card" href="#/inventory"><h2>Medicine inventory</h2><p class="muted small" style="margin:0">${S.plural(g.lowStock || 0, 'medicine')} low or out of stock.</p></a>` : ''}${o.restricted.includes('costs') ? `<a class="card" href="#/costs"><h2>Treatment costs</h2><p class="muted small" style="margin:0">Propose price changes. An administrator approves them before patients see them.</p></a><a class="card" href="#/approvals"><h2>Your requests</h2><p class="muted small" style="margin:0">${S.plural(g.pendingApprovals || 0, 'request')} waiting.</p></a>` : ''}</div>`
                + (o.alerts.length ? `<section class="card" style="margin-top:1rem"><h2>Alerts</h2><ul class="list">${o.alerts.map(a => `<li><span>${esc(a.text)}</span></li>`).join('')}</ul></section>` : '');
            return;
        }
        await baseOverview.render(el, p);
        try {
            const g = o && o.governance; if (!g) return;
            const h = g.hospital, bar = document.createElement('div');
            bar.className = 'notice n-' + (h.trusted ? 'ok' : h.status === 'pending' ? 'info' : 'warn'); bar.style.marginBottom = '1rem';
            bar.innerHTML = `<i class="fa-solid ${h.trusted ? 'fa-circle-check' : 'fa-circle-info'}" aria-hidden="true"></i><span><strong>${h.trusted ? 'Verified by GoaCare' : h.status === 'pending' ? 'Not verified yet' : 'Hospital ' + esc(h.status)}</strong>${h.hospitalCode ? ' · Hospital ID ' + esc(h.hospitalCode) : ''}${h.trusted ? '' : ' · patients see your information labelled as unverified.'}${g.pendingApprovals ? ` · <a href="#/approvals">${S.plural(g.pendingApprovals, 'change')} waiting for approval</a>` : ''}</span>`;
            const first = el.querySelector('.page-head'); if (first) first.insertAdjacentElement('afterend', bar); else el.prepend(bar);
        } catch (e) { /* the base overview already rendered */ }
    } }));
})();
